#!/usr/bin/env python3
# derives: J1.1, J1.3, J1.5, G1.1, G1.2, G1.3, G1.4
"""Compile a scenario to a TLC configuration and classify the run.

Outcomes on stdout are only PASS, FAIL <clause>, or UNEXPLAINED <reason>.
--mutations prints "<name>--mut <outcome>" once per shared scenario.
"""

import json
import os
import re
import shutil
import subprocess
import sys
import tempfile

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
MODEL = os.path.join(ROOT, "model")
JAR = os.path.expanduser("~/projects/tlaplus/tla2tools.jar")
MEMBERS = ("m1", "m2", "m3", "m4", "m5")
SELECTORS = ("coordinator", "follower", "crashed")
SCENARIO_MAX = dict(
    MaxTerm=2, MaxLog=3, MaxMsgs=4, MaxDown=20,
    MaxCmds=0, MaxChanges=0, MaxCrashes=0, MaxDrops=0, MaxRedelivers=0,
)
EXPLORE_MAX = dict(
    MaxTerm=2, MaxLog=3, MaxMsgs=4, MaxDown=0,
    MaxCmds=1, MaxChanges=0, MaxCrashes=0, MaxDrops=0, MaxRedelivers=0,
    MaxEvents=0, Settle=0,
)


class ScenarioError(Exception):
    def __init__(self, reason):
        super().__init__(reason)
        self.reason = reason


def strip_comments(text):
    out = []
    for line in text.splitlines():
        cut = line.split("#", 1)[0]
        out.append(cut)
    return "\n".join(out)


def parse_flow(text, i):
    n = len(text)
    while i < n and text[i] in " \t\r\n":
        i += 1
    if i >= n:
        raise ScenarioError("scenario syntax")
    c = text[i]
    if c == "[":
        i += 1
        items = []
        while True:
            while i < n and text[i] in " \t\r\n":
                i += 1
            if i < n and text[i] == "]":
                return items, i + 1
            item, i = parse_flow(text, i)
            items.append(item)
            while i < n and text[i] in " \t\r\n":
                i += 1
            if i < n and text[i] == ",":
                i += 1
        raise ScenarioError("scenario syntax")
    if c == "{":
        i += 1
        obj = {}
        while True:
            while i < n and text[i] in " \t\r\n":
                i += 1
            if i < n and text[i] == "}":
                return obj, i + 1
            key, i = parse_scalar(text, i, stop=":")
            if not isinstance(key, str) or not key:
                raise ScenarioError("scenario syntax")
            while i < n and text[i] in " \t\r\n":
                i += 1
            if i >= n or text[i] != ":":
                raise ScenarioError("scenario syntax")
            i += 1
            val, i = parse_flow(text, i)
            obj[key] = val
            while i < n and text[i] in " \t\r\n":
                i += 1
            if i < n and text[i] == ",":
                i += 1
        raise ScenarioError("scenario syntax")
    return parse_scalar(text, i, stop=",}]")


def parse_scalar(text, i, stop):
    n = len(text)
    while i < n and text[i] in " \t\r\n":
        i += 1
    if i < n and text[i] in "\"'":
        quote = text[i]
        i += 1
        buf = []
        while i < n and text[i] != quote:
            buf.append(text[i])
            i += 1
        if i >= n:
            raise ScenarioError("scenario syntax")
        return "".join(buf), i + 1
    start = i
    while i < n and text[i] not in stop and text[i] not in "\n":
        i += 1
    word = text[start:i].strip()
    if word == "":
        raise ScenarioError("scenario syntax")
    if word == "true":
        return True, i
    if word == "false":
        return False, i
    if word == "null":
        return None, i
    if re.fullmatch(r"-?\d+", word):
        return int(word), i
    return word, i


def parse_scenario(text):
    body = strip_comments(text)
    lines = body.splitlines()
    data = {}
    i = 0
    while i < len(lines):
        raw = lines[i]
        if not raw.strip():
            i += 1
            continue
        if raw[0] in " \t":
            raise ScenarioError("scenario syntax")
        if ":" not in raw:
            raise ScenarioError("scenario syntax")
        key, rest = raw.split(":", 1)
        key = key.strip()
        rest = rest.strip()
        if key == "steps" and rest == "":
            steps = []
            i += 1
            while i < len(lines):
                line = lines[i]
                if not line.strip():
                    i += 1
                    continue
                if not line.startswith(" ") and not line.startswith("\t"):
                    break
                stripped = line.strip()
                if stripped.startswith("- "):
                    chunk = stripped[2:].strip()
                    i += 1
                    extra = []
                    while i < len(lines) and lines[i].startswith(" ") and not lines[i].strip().startswith("- "):
                        if lines[i].strip():
                            extra.append(lines[i].strip())
                        i += 1
                    blob = chunk
                    if extra:
                        blob = chunk + "\n" + "\n".join(extra) if chunk else "\n".join(extra)
                    if blob.startswith("{"):
                        val, j = parse_flow(blob, 0)
                        if blob[j:].strip():
                            raise ScenarioError("scenario syntax")
                        steps.append(val)
                    else:
                        acc = {}
                        piece = blob
                        while True:
                            if ":" not in piece:
                                raise ScenarioError("scenario syntax")
                            k, r = piece.split(":", 1)
                            val, j = parse_flow(r, 0)
                            acc[k.strip()] = val
                            piece = r[j:].strip()
                            if not piece:
                                break
                        steps.append(acc)
                else:
                    raise ScenarioError("scenario syntax")
            data["steps"] = steps
            continue
        if rest == "":
            raise ScenarioError("scenario syntax")
        val, j = parse_flow(rest, 0)
        if rest[j:].strip():
            raise ScenarioError("scenario syntax")
        data[key] = val
        i += 1
    if "initial" not in data or "steps" not in data:
        raise ScenarioError("scenario syntax")
    if not isinstance(data["steps"], list):
        raise ScenarioError("scenario syntax")
    end = data.get("end") or {}
    bound = data.get("bound") or {}
    if not isinstance(end, dict) or "settle" not in end:
        raise ScenarioError("scenario syntax")
    if not isinstance(bound, dict) or "events" not in bound:
        raise ScenarioError("scenario syntax")
    if not isinstance(end["settle"], int) or not isinstance(bound["events"], int):
        raise ScenarioError("scenario syntax")
    if end["settle"] < 0 or bound["events"] < 0:
        raise ScenarioError("scenario syntax")
    if not isinstance(data["initial"], list) or not data["initial"]:
        raise ScenarioError("scenario syntax")
    return data


def tla_string(s):
    return '"' + str(s).replace("\\", "\\\\").replace('"', '\\"') + '"'


def check_member(name, allow_selector=False):
    if name in MEMBERS:
        return
    if allow_selector and name in SELECTORS:
        return
    if name in SELECTORS and not allow_selector:
        raise ScenarioError("scenario syntax")
    raise ScenarioError("unknown member")


def normalise_steps(steps):
    out = []
    for step in steps:
        if not isinstance(step, dict) or "at" not in step or "do" not in step:
            raise ScenarioError("scenario syntax")
        at = step["at"]
        do = step["do"]
        if at == "start":
            trig = {"event": "start"}
        elif isinstance(at, dict) and "event" in at:
            trig = {
                "event": str(at["event"]),
                "member": "" if "member" not in at else str(at["member"]),
                "index": -1 if "index" not in at else at["index"],
                "epoch": -1 if "epoch" not in at else at["epoch"],
                "kind": "" if "kind" not in at else str(at["kind"]),
                "status": "" if "status" not in at else str(at["status"]),
                "op": "" if "op" not in at else str(at["op"]),
                "target": "" if "target" not in at else str(at["target"]),
            }
            for fld in ("index", "epoch"):
                if not isinstance(trig[fld], int):
                    raise ScenarioError("scenario syntax")
            if trig["member"] not in ("",) + MEMBERS + SELECTORS:
                raise ScenarioError("unknown member")
            if trig["target"] not in ("",) + MEMBERS + SELECTORS:
                raise ScenarioError("unknown member")
        else:
            raise ScenarioError("scenario syntax")
        if not isinstance(do, dict):
            raise ScenarioError("scenario syntax")
        action = action_of(do)
        out.append({"trig": trig, "action": action})
    return out


def action_of(do):
    keys = set(do)
    if "command" in keys:
        if "at" not in do:
            raise ScenarioError("scenario syntax")
        at = str(do["at"])
        check_member(at, allow_selector=True)
        return {"kind": "command", "at": at, "target": "", "cmd": str(do["command"]), "links": []}
    if "add" in keys or "remove" in keys:
        op = "add" if "add" in keys else "remove"
        if "at" not in do:
            raise ScenarioError("scenario syntax")
        at = str(do["at"])
        target = str(do[op])
        check_member(at, allow_selector=True)
        check_member(target, allow_selector=True)
        return {"kind": op, "at": at, "target": target, "cmd": "", "links": []}
    if "crash" in keys or "restart" in keys:
        op = "crash" if "crash" in keys else "restart"
        at = str(do[op])
        check_member(at, allow_selector=True)
        return {"kind": op, "at": at, "target": "", "cmd": "", "links": []}
    if "cut" in keys or "drop" in keys:
        op = "cut" if "cut" in keys else "drop"
        links = do[op]
        if not isinstance(links, list):
            raise ScenarioError("scenario syntax")
        norm = []
        for pair in links:
            if not isinstance(pair, list) or len(pair) != 2:
                raise ScenarioError("scenario syntax")
            a, b = str(pair[0]), str(pair[1])
            check_member(a, allow_selector=True)
            check_member(b, allow_selector=True)
            norm.append([a, b])
        return {"kind": op, "at": "", "target": "", "cmd": "", "links": norm}
    if "heal" in keys:
        return {"kind": "heal", "at": "", "target": "", "cmd": "", "links": []}
    raise ScenarioError("scenario syntax")


def selector_refs(step):
    refs = set()
    trig = step["trig"]
    for fld in ("member", "target"):
        if trig.get(fld) in SELECTORS:
            refs.add(trig[fld])
    act = step["action"]
    for fld in ("at", "target"):
        if act[fld] in SELECTORS:
            refs.add(act[fld])
    for a, b in act["links"]:
        if a in SELECTORS:
            refs.add(a)
        if b in SELECTORS:
            refs.add(b)
    return refs


def static_check(steps):
    seen_crash = False
    seen_elected = False
    for step in steps:
        if step["trig"]["event"] == "Elected":
            seen_elected = True
        refs = selector_refs(step)
        if "crashed" in refs and not seen_crash:
            raise ScenarioError("crashed before crash")
        if step["trig"]["event"] == "start" and not seen_elected:
            if "coordinator" in refs:
                raise ScenarioError("coordinator before election")
            if "follower" in refs:
                raise ScenarioError("follower before election")
        if step["action"]["kind"] == "crash":
            seen_crash = True


def trig_tla(trig):
    return (
        "[event |-> {event}, member |-> {member}, index |-> {index}, "
        "epoch |-> {epoch}, kind |-> {kind}, status |-> {status}, "
        "op |-> {op}, target |-> {target}]"
    ).format(
        event=tla_string(trig["event"]),
        member=tla_string(trig.get("member", "")),
        index=trig.get("index", -1),
        epoch=trig.get("epoch", -1),
        kind=tla_string(trig.get("kind", "")),
        status=tla_string(trig.get("status", "")),
        op=tla_string(trig.get("op", "")),
        target=tla_string(trig.get("target", "")),
    )


def links_tla(links):
    if not links:
        return "<<>>"
    inner = ", ".join("<<{0}, {1}>>".format(tla_string(a), tla_string(b)) for a, b in links)
    return "<<{0}>>".format(inner)


def action_tla(act):
    return (
        "[kind |-> {kind}, at |-> {at}, target |-> {target}, cmd |-> {cmd}, links |-> {links}]"
    ).format(
        kind=tla_string(act["kind"]),
        at=tla_string(act["at"]),
        target=tla_string(act["target"]),
        cmd=tla_string(act["cmd"]),
        links=links_tla(act["links"]),
    )


def config_tla(names):
    for name in names:
        check_member(str(name), allow_selector=False)
    if not names:
        return "{m1, m2, m3, m4, m5} \\ {m1, m2, m3, m4, m5}"
    return "{" + ", ".join(str(n) for n in names) + "}"


BLANK_TRIG = (
    '[event |-> "none", member |-> "", index |-> -1, epoch |-> -1, '
    'kind |-> "", status |-> "", op |-> "", target |-> ""]'
)
BLANK_ACT = '[kind |-> "none", at |-> "", target |-> "", cmd |-> "", links |-> <<>>]'


