def prepare_scenario(path, bug):
    with open(path, encoding="utf-8") as fh:
        data = parse_scenario(fh.read())
    steps = normalise_steps(data["steps"])
    static_check(steps)
    bounds = dict(SCENARIO_MAX)
    bounds["MaxEvents"] = data["bound"]["events"]
    bounds["Settle"] = data["end"]["settle"]
    return data["initial"], bounds, steps, "scenario", False, bug


def prepare_explore():
    init = ["m1", "m2", "m3", "m4"]
    return init, dict(EXPLORE_MAX), [], "explore", True, "none"


def run_id_of(path, mutation):
    stem = os.path.splitext(os.path.basename(path))[0]
    stem = re.sub(r"[^A-Za-z0-9._-]", "_", stem) or "scenario"
    if mutation:
        return stem + "--mut"
    return stem


CLAUSE = {"J11": "J1.1", "J13": "J1.3", "J15": "J1.5"}


def parse_tla_string(text, i):
    if text[i] != '"':
        raise ValueError("string")
    i += 1
    buf = []
    while i < len(text):
        ch = text[i]
        if ch == "\\":
            nxt = text[i + 1]
            buf.append({"n": "\n", "t": "\t", '"': '"', "\\": "\\"}.get(nxt, nxt))
            i += 2
            continue
        if ch == '"':
            return "".join(buf), i + 1
        buf.append(ch)
        i += 1
    raise ValueError("unterminated string")


def parse_string_seq(text, i):
    while i < len(text) and text[i].isspace():
        i += 1
    if not text.startswith("<<", i):
        raise ValueError("seq")
    i += 2
    items = []
    while True:
        while i < len(text) and text[i].isspace():
            i += 1
        if text.startswith(">>", i):
            return items, i + 2
        item, i = parse_tla_string(text, i)
        items.append(item)
        while i < len(text) and text[i].isspace():
            i += 1
        if i < len(text) and text[i] == ",":
            i += 1


def trace_events(log):
    events = []
    for match in re.finditer(r"lastObs\s*=\s*", log):
        try:
            items, _ = parse_string_seq(log, match.end())
        except ValueError:
            continue
        events.extend(items)
    return events


def causes_of(proc, seq):
    if not proc:
        return []
    return [{"proc": proc, "seq": int(seq)}]


def config_list(text):
    if not text:
        return []
    return text.split(",")


def links_of(detail):
    if not detail:
        return []
    out = []
    for bit in detail.split(";"):
        if ">" in bit:
            a, b = bit.split(">", 1)
            out.append([a, b])
    return out


def event_record(line, run):
    parts = line.split("|")
    kind = parts[0]
    base = {"run": run, "side": "model", "causes": []}
    if kind == "Elected":
        voters = []
        if parts[5]:
            for bit in parts[5].split(";"):
                proc, seq = bit.split(":")
                voters.append({"proc": proc, "seq": int(seq)})
        base.update({
            "proc": parts[1], "seq": int(parts[2]), "event": "Elected",
            "epoch": int(parts[3]), "config": config_list(parts[4]),
            "causes": voters,
        })
        return base
    if kind == "Appended":
        payload = "|".join(parts[6:-2])
        cause_proc, cause_seq = parts[-2], parts[-1]
        if parts[5] == "config":
            payload = config_list(payload)
        base.update({
            "proc": parts[1], "seq": int(parts[2]), "event": "Appended",
            "index": int(parts[3]), "epoch": int(parts[4]), "kind": parts[5],
            "payload": payload, "causes": causes_of(cause_proc, cause_seq),
        })
        return base
    if kind == "Truncated":
        base.update({
            "proc": parts[1], "seq": int(parts[2]), "event": "Truncated",
            "from_index": int(parts[3]),
        })
        return base
    if kind == "Committed":
        base.update({
            "proc": parts[1], "seq": int(parts[2]), "event": "Committed",
            "index": int(parts[3]), "epoch": int(parts[4]),
            "causes": causes_of(parts[5], parts[6]),
        })
        return base
    if kind == "ConfigInEffect":
        base.update({
            "proc": parts[1], "seq": int(parts[2]), "event": "ConfigInEffect",
            "config": config_list(parts[3]), "index": int(parts[4]),
            "causes": causes_of(parts[5], parts[6]),
        })
        return base
    if kind == "ChangeRequested":
        base.update({
            "proc": parts[1], "seq": int(parts[2]), "event": "ChangeRequested",
            "op": parts[3], "target": parts[4],
        })
        return base
    if kind == "ChangeReplied":
        base.update({
            "proc": parts[1], "seq": int(parts[2]), "event": "ChangeReplied",
            "op": parts[3], "target": parts[4], "status": parts[5],
        })
        return base
    if kind == "Fault":
        fault = parts[3]
        detail = parts[4] if len(parts) > 4 else ""
        base.update({"proc": "env", "seq": int(parts[2]), "event": "Fault"})
        if fault in ("cut", "drop"):
            base[fault] = links_of(detail)
        elif fault == "heal":
            base["heal"] = True
        elif fault in ("crash", "restart"):
            base[fault] = detail
        else:
            base["action"] = fault
        return base
    raise ValueError(line)


def write_observe(log, run):
    lines = trace_events(log)
    if not lines:
        return
    dest_dir = os.path.join(MODEL, "observe")
    os.makedirs(dest_dir, exist_ok=True)
    path = os.path.join(dest_dir, run + ".jsonl")
    with open(path, "w", encoding="utf-8") as fh:
        for line in lines:
            fh.write(json.dumps(event_record(line, run), separators=(",", ":")) + "\n")


def classify(log, rc, explore=False):
    violated = re.search(r"Invariant ([A-Za-z0-9_]+) is violated", log)
    if violated:
        name = violated.group(1)
        if name in CLAUSE:
            return "FAIL " + CLAUSE[name]
        return "UNEXPLAINED tlc-error"
    # PASS only when TLC has exhausted the state space. A marker printed
    # on the way is not enough: the run may still have been killed.
    finished = "Model checking completed. No error has been found." in log
    completed = "COMPLETED_MARKER" in log
    event_bound = "EVENT_BOUND_MARKER" in log
    oom = rc in (137, 143, 9) or any(
        s in log for s in (
            "OutOfMemoryError", "Java heap space", "GC overhead",
            "Cannot allocate", "Killed",
        )
    )
    if finished and not oom:
        if explore or completed:
            return "PASS"
        if event_bound:
            return "UNEXPLAINED steps"
        return "UNEXPLAINED bound"
    if event_bound and not oom:
        return "UNEXPLAINED steps"
    if oom or "MODEL_BOUND_MARKER" in log or rc == 0:
        return "UNEXPLAINED bound"
    if "Error:" in log or rc != 0:
        return "UNEXPLAINED tlc-error"
    return "UNEXPLAINED bound"


def tlc(work, log_path):
    cmd = [
        "systemd-run", "--user", "--scope", "-q",
        "-p", "MemoryMax=24G", "-p", "MemorySwapMax=0",
        "java", "-Xmx8g", "-XX:+UseParallelGC", "-jar", JAR,
        "-deadlock", "-workers", "16", "-fpmem", "0.05",
        "-config", "Run.cfg",
        "-metadir", os.path.join(work, "meta"),
        "Run.tla",
    ]
    with open(log_path, "w", encoding="utf-8") as fh:
        proc = subprocess.Popen(
            cmd, cwd=work, stdout=fh, stderr=subprocess.STDOUT
        )
        rc = proc.wait()
    with open(log_path, encoding="utf-8", errors="replace") as fh:
        text = fh.read()
    return rc, text


def execute(prep, run):
    init, bounds, steps, mode, ambient, bug = prep
    work = tempfile.mkdtemp(prefix="dmodel-")
    log_dir = os.environ.get("DMODEL_LOG_DIR", "/tmp/dmodel-logs")
    os.makedirs(log_dir, exist_ok=True)
    log_path = os.path.join(log_dir, run + ".log")
    try:
        write_run(work, init=init, bounds=bounds, bug=bug, mode=mode,
                  steps=steps, ambient=ambient)
        rc, text = tlc(work, log_path)
        outcome = classify(text, rc, explore=(mode == "explore"))
        if outcome.startswith("FAIL"):
            try:
                write_observe(text, run)
            except ValueError:
                sys.stderr.write("observe parse failed for {0}\n".format(run))
        return outcome, 0 if not outcome.endswith("tlc-error") else 2
    finally:
        shutil.rmtree(work, ignore_errors=True)


def emit(line):
    sys.stdout.write(line + "\n")
    sys.stdout.flush()


def main(argv):
    if len(argv) == 1 and argv[0] == "--explore":
        outcome, code = execute(prepare_explore(), "explore")
        emit(outcome)
        return code
    if len(argv) == 1 and argv[0] == "--mutations":
        code = 0
        for n in range(1, 9):
            path = os.path.join(ROOT, "replay", "scenarios", "S{0}.yaml".format(n))
            bug = "S{0}".format(n)
            run = "S{0}--mut".format(n)
            try:
                prep = prepare_scenario(path, bug)
            except ScenarioError as exc:
                emit("{0} UNEXPLAINED {1}".format(run, exc.reason))
                continue
            outcome, rc = execute(prep, run)
            code = max(code, rc)
            emit("{0} {1}".format(run, outcome))
        return code
    if len(argv) == 3 and argv[0] == "--mutation":
        bug, path = argv[1], argv[2]
        run = run_id_of(path, True)
        try:
            prep = prepare_scenario(path, bug)
        except ScenarioError as exc:
            emit("UNEXPLAINED " + exc.reason)
            return 0
        outcome, code = execute(prep, run)
        emit(outcome)
        return code
    if len(argv) == 1 and not argv[0].startswith("--"):
        path = argv[0]
        run = run_id_of(path, False)
        try:
            prep = prepare_scenario(path, "none")
        except ScenarioError as exc:
            emit("UNEXPLAINED " + exc.reason)
            return 0
        except OSError:
            emit("UNEXPLAINED scenario syntax")
            return 2
        outcome, code = execute(prep, run)
        emit(outcome)
        return code
    sys.stderr.write("usage: run.sh <scenario> | run.sh --mutations | run.sh --explore\n")
    return 2


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
